changes.content:
{
  "schema_version": 1,
  "selected_strategy": "shadow-copy-cas",
  "rationale": "Migrate tenants independently using the existing copy worker, router, and stores. Keep the legacy store as the sole application writer while an idempotent shadow copy advances from a durable per-tenant checkpoint. Verify the ordered event identities and content before freezing one tenant, then copy and verify the final delta. Complete the guarded route change and resume writes within 30 seconds; if the deadline cannot be met before cutover, resume the legacy route and reuse the checkpoint. After cutover, the new store is authoritative and any repair moves forward there. Retain legacy data as recovery evidence.",
  "constraints_addressed": ["C1", "C2", "C3", "C4", "C5", "C6", "C7"],
  "rejected_strategies": {
    "global-stop-rewrite": "Stopping all writes violates C1 and prevents independent tenant migration under C7.",
    "dual-write-backfill": "Synchronous or asynchronous dual writes violate C2.",
    "cdc-mirror-cutover": "Introducing a change-data-capture pipeline and lag monitor violates C6."
  },
  "plan": [
    {
      "step_id": "p1",
      "operation": "capture_initial_watermark",
      "depends_on": [],
      "satisfies": ["C3", "C7"]
    },
    {
      "step_id": "p2",
      "operation": "shadow_copy",
      "depends_on": ["p1"],
      "satisfies": ["C2", "C3", "C6", "C7"]
    },
    {
      "step_id": "p3",
      "operation": "verify_shadow",
      "depends_on": ["p2"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p4",
      "operation": "freeze_tenant_writes",
      "depends_on": ["p3"],
      "satisfies": ["C1", "C7"]
    },
    {
      "step_id": "p5",
      "operation": "capture_final_watermark",
      "depends_on": ["p4"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p6",
      "operation": "copy_delta",
      "depends_on": ["p5"],
      "satisfies": ["C3", "C4"]
    },
    {
      "step_id": "p7",
      "operation": "verify_final",
      "depends_on": ["p6"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p8",
      "operation": "cas_route",
      "depends_on": ["p7"],
      "satisfies": ["C2", "C4", "C5", "C7"]
    },
    {
      "step_id": "p9",
      "operation": "unfreeze_tenant_writes",
      "depends_on": ["p8"],
      "satisfies": ["C1", "C5"]
    },
    {
      "step_id": "p10",
      "operation": "monitor",
      "depends_on": ["p9"],
      "satisfies": ["C5", "C7"]
    }
  ],
  "cutover_gate": {
    "mode": "compare_and_swap",
    "requires": ["legacy_route_version", "final_watermark", "verification_passed"]
  },
  "rollback": {
    "before_cutover": "resume_legacy_and_reuse_checkpoint",
    "after_cutover": "forward_repair_on_new_store"
  },
  "max_tenant_write_pause_seconds": 30
}
